[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Global Internet Usage Comparison - Infographic Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    background: #060d1a;
    display: flex;
    justify-content: center;
    padding: 20px;
  }

  .poster {
    width: 1200px;
    background: linear-gradient(180deg, #080f20 0%, #0a1628 15%, #0c1a33 100%);
    padding: 80px 72px 72px;
    position: relative;
    overflow: hidden;
  }

  /* Subtle globe/network background motif */
  .poster::before {
    content: '';
    position: absolute;
    top: -180px;
    right: -180px;
    width: 700px;
    height: 700px;
    border: 1px solid rgba(20, 184, 166, 0.06);
    border-radius: 50%;
    pointer-events: none;
  }
  .poster::after {
    content: '';
    position: absolute;
    bottom: 200px;
    left: -200px;
    width: 600px;
    height: 600px;
    border: 1px solid rgba(6, 182, 212, 0.05);
    border-radius: 50%;
    pointer-events: none;
  }

  .poster > * { position: relative; z-index: 1; }

  /* Title Section */
  .title-section {
    text-align: center;
    margin-bottom: 48px;
    border-bottom: 1px solid rgba(20, 184, 166, 0.15);
    padding-bottom: 48px;
  }
  .title-kicker {
    font-size: 13px;
    font-weight: 500;
    letter-spacing: 0.28em;
    text-transform: uppercase;
    color: #14b8a6;
    margin-bottom: 16px;
  }
  .title-main {
    font-size: 44px;
    font-weight: 800;
    color: #ffffff;
    line-height: 1.15;
    letter-spacing: -0.02em;
    margin-bottom: 12px;
  }
  .title-sub {
    font-size: 16px;
    font-weight: 400;
    color: rgba(255, 255, 255, 0.55);
    max-width: 680px;
    margin: 0 auto;
    line-height: 1.5;
  }

  /* Hero Stat */
  .hero-stat {
    text-align: center;
    margin-bottom: 64px;
    padding: 40px 0;
  }
  .hero-number {
    font-size: 120px;
    font-weight: 900;
    color: #ffffff;
    line-height: 1;
    letter-spacing: -0.03em;
    background: linear-gradient(135deg, #ffffff 0%, #14b8a6 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 8px;
  }
  .hero-context {
    font-size: 20px;
    font-weight: 500;
    color: rgba(255,255,255,0.6);
    letter-spacing: 0.05em;
  }
  .hero-source {
    font-size: 12px;
    color: rgba(255,255,255,0.3);
    margin-top: 8px;
  }

  /* Section styling */
  .section {
    margin-bottom: 56px;
  }
  .section-header {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 28px;
  }
  .section-number {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: rgba(20, 184, 166, 0.12);
    border: 1px solid rgba(20, 184, 166, 0.3);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    font-weight: 700;
    color: #14b8a6;
    flex-shrink: 0;
  }
  .section-title {
    font-size: 26px;
    font-weight: 700;
    color: #ffffff;
    letter-spacing: -0.01em;
  }

  /* Two-column layout */
  .two-col {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 40px;
  }

  /* Infographic container */
  .infographic-container {
    background: rgba(255,255,255,0.02);
    border: 1px solid rgba(20, 184, 166, 0.08);
    border-radius: 12px;
    padding: 24px;
    min-height: 320px;
  }
  .infographic-container.wide {
    grid-column: 1 / -1;
  }

  /* Highlight cards */
  .highlight-row {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-top: 16px;
  }
  .highlight-card {
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(20, 184, 166, 0.1);
    border-radius: 10px;
    padding: 24px 20px;
    text-align: center;
  }
  .highlight-value {
    font-size: 28px;
    font-weight: 800;
    color: #14b8a6;
    line-height: 1;
    margin-bottom: 6px;
  }
  .highlight-label {
    font-size: 12px;
    font-weight: 500;
    color: rgba(255,255,255,0.5);
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }

  /* Takeaways */
  .takeaways {
    margin-top: 8px;
    padding: 32px 36px;
    background: rgba(20, 184, 166, 0.04);
    border: 1px solid rgba(20, 184, 166, 0.1);
    border-radius: 12px;
  }
  .takeaways-title {
    font-size: 18px;
    font-weight: 700;
    color: #14b8a6;
    margin-bottom: 16px;
    letter-spacing: 0.04em;
    text-transform: uppercase;
  }
  .takeaway-item {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    margin-bottom: 10px;
    font-size: 14px;
    color: rgba(255,255,255,0.7);
    line-height: 1.5;
  }
  .takeaway-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #06b6d4;
    margin-top: 6px;
    flex-shrink: 0;
  }

  /* Footer */
  .poster-footer {
    margin-top: 56px;
    padding-top: 24px;
    border-top: 1px solid rgba(255,255,255,0.06);
    display: flex;
    justify-content: space-between;
    font-size: 11px;
    color: rgba(255,255,255,0.25);
    letter-spacing: 0.04em;
  }

  /* Special callout for China/India */
  .callout-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-top: 24px;
    margin-bottom: 40px;
  }
  .callout-card {
    padding: 28px 32px;
    border-radius: 12px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .callout-card.china {
    background: linear-gradient(135deg, rgba(239, 68, 68, 0.08) 0%, rgba(239, 68, 68, 0.03) 100%);
    border: 1px solid rgba(239, 68, 68, 0.15);
  }
  .callout-card.india {
    background: linear-gradient(135deg, rgba(251, 146, 60, 0.08) 0%, rgba(251, 146, 60, 0.03) 100%);
    border: 1px solid rgba(251, 146, 60, 0.15);
  }
  .callout-country {
    font-size: 13px;
    font-weight: 600;
    color: rgba(255,255,255,0.5);
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 4px;
  }
  .callout-value {
    font-size: 42px;
