const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  // Set viewport to match poster width at 2x for retina quality
  await page.setViewportSize({ width: 1200, height: 800 });

  const htmlPath = 'file://' + path.resolve('/app/output/poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle', timeout: 30000 });

  // Wait for infographic renders to complete
  await page.waitForTimeout(3000);

  // Get the actual poster height
  const posterHeight = await page.evaluate(() => {
    const poster = document.querySelector('.poster');
    return poster ? poster.offsetHeight + 40 : 5000;
  });

  // Set viewport to full poster height
  await page.setViewportSize({ width: 1200, height: Math.ceil(posterHeight) });

  // Take screenshot at 2x scale
  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true,
    clip: null
  });

  console.log('Poster height:', posterHeight);
  console.log('PNG saved to /app/output/final_poster.png');

  await browser.close();
})();

