const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  // Capture console messages
  const logs = [];
  page.on('console', msg => logs.push(`[${msg.type()}] ${msg.text()}`));
  page.on('pageerror', err => logs.push(`[PAGE ERROR] ${err.message}`));

  await page.setViewportSize({ width: 1200, height: 800 });

  const htmlPath = 'file://' + path.resolve('/app/output/poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle', timeout: 30000 });

  await page.waitForTimeout(4000);

  // Check if SVG elements exist in the infographic containers
  const svgCount = await page.evaluate(() => {
    const containers = ['#chart-population', '#chart-penetration', '#chart-social'];
    const results = {};
    for (const id of containers) {
      const el = document.querySelector(id);
      if (el) {
        const svg = el.querySelector('svg');
        results[id] = svg ? `SVG found (${svg.getAttribute('width')}x${svg.getAttribute('height')})` : 'No SVG';
      } else {
        results[id] = 'Container not found';
      }
    }
    return results;
  });

  console.log('SVG status:', JSON.stringify(svgCount, null, 2));

  // Get the actual poster height
  const posterHeight = await page.evaluate(() => {
    const poster = document.querySelector('.poster');
    return poster ? poster.offsetHeight + 40 : 5000;
  });

  await page.setViewportSize({ width: 1200, height: Math.ceil(posterHeight) });

  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true
  });

  console.log('Poster height:', posterHeight);
  console.log('Console logs:', logs.join('\n  '));
  console.log('PNG saved to /app/output/final_poster.png');

  await browser.close();
})();
