const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  const logs = [];
  page.on('pageerror', err => logs.push('[PAGE ERROR] ' + err.message));

  // A1 portrait at high resolution: 1600px width with matching ratio
  const posterW = 1600;
  const posterH = 2260;
  await page.setViewportSize({ width: posterW + 40, height: posterH + 40 });

  const htmlPath = 'file://' + path.resolve('/app/output/poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle', timeout: 30000 });

  await page.waitForTimeout(4000);

  // Check SVGs rendered
  const svgCheck = await page.evaluate(() => {
    const ids = ['#chart-population', '#chart-penetration', '#chart-social', '#chart-ecommerce'];
    const r = {};
    ids.forEach(id => {
      const el = document.querySelector(id);
      r[id] = el && el.querySelector('svg') ? 'OK' : 'MISSING';
    });
    return r;
  });
  console.log('Charts:', JSON.stringify(svgCheck));

  // Screenshot just the poster element
  const posterEl = await page.$('.poster');
  if (posterEl) {
    await posterEl.screenshot({ path: '/app/output/final_poster.png' });
    console.log('PNG saved (element screenshot)');
  } else {
    await page.screenshot({ path: '/app/output/final_poster.png', fullPage: true });
    console.log('PNG saved (full page fallback)');
  }

  if (logs.length) console.log('Errors:', logs.join('\n  '));

  await browser.close();
})();

